using System;using System.Linq;using System.Drawing;using System.Collections.Generic;using System.Windows.Media.Media3D;
namespace GearLab {
 public static class LegacyWaveFastModel {
  public static WaveParameters From(Parameters p){return new WaveParameters{Flat=true,Ratio=(int)Math.Round(p.Ratio),Module=p.Module,Thickness=p.Thickness,Wall=p.WaveWall,RingWall=p.Wall,Bore=p.Shaft,OutputBore=p.OutputShaft,Clearance=p.Clearance,BearingWall=p.WaveBearingWall,InputTorque=p.InputTorque,InputRpm=p.InputRpm,Efficiency=p.Efficiency,LoadTorque=p.LoadTorque};}
  public static double Radius(Parameters p){return p.Module*(p.Ratio+2.25)+p.Wall;}
  public static bool Fit(Parameters p){if(p.Overall<=0)return true;double m=Math.Floor((p.Overall/2-p.Wall)/(p.Ratio+2.25)*10000)/10000;if(m<.15||m>2)return false;var copy=Engine.Clone(p);copy.Module=m;if(!Calculate(copy).Valid)return false;p.Module=m;return true;}
  public static Result Calculate(Parameters input){var p=Engine.Clone(input);var r=new Result{P=p};try{if(p.Ratio!=Math.Round(p.Ratio))throw new Exception("Для волнового редуктора отношение должно быть целым: 20–120.");var w=From(p);w.Validate();if(p.Overall<0||p.Overall>2000||p.MotorPreset<0||p.MotorPreset>=Engine.PresetNames.Length)throw new Exception("Проверьте габарит и размерный набор.");if(new[]{p.MotorFrame,p.MotorMount,p.MotorPilot,p.MotorHole,p.MotorLength}.Any(x=>double.IsNaN(x)||double.IsInfinity(x)||x<0))throw new Exception("Недопустимые размеры мотора.");if(p.MotorFrame>0&&(p.MotorMount+p.MotorHole>=p.MotorFrame||p.MotorPilot>=p.MotorFrame))throw new Exception("Крепления не помещаются на торце мотора.");r.Wave=w;r.Actual=w.Ratio;r.Z1=w.FlexTeeth;r.Z2=w.RingTeeth;r.Width=r.Height=2*Radius(p);r.Depth=2*p.Thickness+p.Clearance+2*Math.Max(2,p.Wall*.75)+15;if(p.Overall>0&&r.Width>p.Overall+.025)r.Error("Волновой узел не помещается в заданный габарит. Включите автоподбор или увеличьте размер.","Overall","Module");r.Gear1=WaveDiagram.Profile(w,false,0);r.Gear2=WaveDiagram.Profile(w,true,0);r.Metric("Зубья: гибкое / неподвижное / выходное",w.FlexTeeth+" / "+w.RingTeeth+" / "+w.FlexTeeth);r.Metric("Направление выхода","Противоположно входу");r.Metric("Выходная скорость",Engine.F(w.OutputRpm)+" об/мин");r.Metric("Момент при заданном КПД",Engine.F(w.OutputTorque)+" Н·м");r.Metric("Требуемый входной момент",Engine.F(w.RequiredTorque)+" Н·м");r.Metric("Входная мощность",Engine.F(w.InputPower)+" Вт");foreach(var row in WaveDiagram.Rows(w))r.Add(row[0],row[1],row[2],"Геометрическая компоновка");r.Notes.Add("Плоская волновая схема: неподвижный венец z+2, гибкое колесо z, выходной венец z. nвых=−nвх/i; Tвых=Tвх·i·КПД.");r.Notes.Add("Предпросмотр строится из параметрических профилей тем же способом, что у остальных редукторов. Точные B-rep поверхности рассчитываются при STEP-экспорте.");r.Notes.Add("Эллиптическая деформация задана. Контакт, упругость, прочность, ресурс и допустимый момент не рассчитаны.");}catch(Exception ex){r.Error(ex.Message,"Ratio","Module","WaveWall","Wall","Shaft","OutputShaft");}return r;}
  public static void Add(CadAssembly a,Result r){if(!r.Valid)return;var p=r.P;var w=r.Wave;double m=w.Module,t=w.Thickness,g=w.Clearance,plate=Math.Max(2,w.RingWall*.75),total=2*t+g,outer=Radius(p),root=m*(w.Ratio-1.25),inner=root-w.Wall,rx=inner*(1+1.0/w.Ratio)-g,ry=inner*(1-1.0/w.Ratio)-g,bolt=Math.Max(1.2,Math.Min(2,w.RingWall*.3)),br=outer-bolt-1,hub=Math.Max(w.OutputBore/2+5,m*w.Ratio*.30),wr=(outer-w.RingWall+hub)/2,window=Math.Max(1,(outer-w.RingWall-hub)*.40);
   Func<double,double,CadLoop> circle=(x,y)=>CadLoop.Round(0,0,x);Func<double,double,CadLoop> ellipse=(x,y)=>CadLoop.Polygon(Enumerable.Range(0,128).Select(i=>new PointF((float)(x*Math.Cos(Engine.Tau*i/128)),(float)(y*Math.Sin(Engine.Tau*i/128)))).ToArray());
   Func<string,string,string,Color,CadPart> part=(id,label,role,color)=>{var q=new CadPart("wave_"+id,label,role,color);a.Parts.Add(q);return q;};Action<CadPart,double,double,CadLoop,IEnumerable<CadLoop>> section=(q,z,h,o,cutouts)=>q.Sections.Add(new CadSection(z,z+h,o,cutouts));
   Func<double,double,List<CadLoop>> holes=(radius,offset)=>Enumerable.Range(0,6).Select(i=>CadLoop.Round(radius*Math.Cos(Engine.Tau*i/6+offset),radius*Math.Sin(Engine.Tau*i/6+offset),bolt)).ToList();var fixedHoles=holes(br,0);var outputHoles=holes(br,Math.PI/6);var windows=Enumerable.Range(0,6).Select(i=>CadLoop.Round(wr*Math.Cos(Engine.Tau*(i+.5)/6),wr*Math.Sin(Engine.Tau*(i+.5)/6),window)).ToList();var steel=Color.FromArgb(155,169,184);
   var ring=part("ring","Неподвижный венец и моторный фланец","housing",Color.FromArgb(105,135,158));section(ring,-plate-g,plate,CadLoop.Round(0,0,outer),new[]{CadLoop.Round(0,0,Math.Max(w.OutputBore/2+3,root*.45))}.Concat(fixedHoles));section(ring,-g,g,CadLoop.Round(0,0,outer),new[]{CadLoop.Round(0,0,outer-w.RingWall*.7)}.Concat(fixedHoles));section(ring,0,t,CadLoop.Round(0,0,outer),new[]{CadLoop.Polygon(r.Gear2)}.Concat(fixedHoles));
   var flex=part("flex","Гибкое зубчатое колесо","gear",Color.FromArgb(221,148,58));section(flex,0,total,CadLoop.Polygon(r.Gear1),new[]{ellipse(inner*(1+1.0/w.Ratio),inner*(1-1.0/w.Ratio))});
   var bearing=part("bearing","Гибкий подшипник генератора","bearing",steel);section(bearing,0,total,ellipse(rx,ry),new[]{ellipse(rx-w.BearingWall,ry-w.BearingWall)});
   var generator=part("generator","Генератор волн и входной вал","shaft",Color.FromArgb(47,139,199));section(generator,-plate-g-8,plate+g+8,CadLoop.Round(0,0,p.Shaft/2),null);section(generator,0,total,ellipse(rx-w.BearingWall-g,ry-w.BearingWall-g),null);
   var output=part("output","Выходной венец, зубчатый диск и вал","gear",steel);var dynamicProfile=CadLoop.Polygon(Engine.Involute(w.FlexTeeth,m,true));section(output,t+g,t,CadLoop.Round(0,0,outer),new[]{dynamicProfile}.Concat(outputHoles));section(output,total,g,CadLoop.Round(0,0,outer),new[]{CadLoop.Round(0,0,outer-w.RingWall*.7)}.Concat(outputHoles));section(output,total+g,plate,CadLoop.Round(0,0,outer),windows.Concat(outputHoles));double front=total+g+plate;section(output,front,Math.Max(2,plate),CadLoop.Polygon(Engine.Involute(w.FlexTeeth,m,false)),windows);section(output,front+Math.Max(2,plate),3,CadLoop.Round(0,0,hub),null);section(output,front+Math.Max(2,plate)+3,12,CadLoop.Round(0,0,p.OutputShaft/2),null);
   for(int i=0;i<6;i++){double angle=Engine.Tau*i/6;var q=part("bolt"+(i+1),"Винт неподвижного фланца","fastener",steel);section(q,-plate-g,t+plate+g,CadLoop.Round(br*Math.Cos(angle),br*Math.Sin(angle),bolt*.85),null);angle+=Math.PI/6;var b=part("output_bolt"+(i+1),"Винт выходного фланца","fastener",steel);double x=br*Math.Cos(angle),y=br*Math.Sin(angle);section(b,t+g,t+g+plate,CadLoop.Round(x,y,bolt*.85),null);section(b,total+g+plate,1.7,CadLoop.Round(x,y,bolt*1.5),new[]{CadLoop.Round(x,y,bolt*.5)});}
   a.Notes.Add("Быстрый параметрический предпросмотр; точный STEP строится отдельно при экспорте. Крепёж упрощён, без резьбы.");
  }
 }
}
